settings.custom_liquid:
{% comment %}
  GulfSouq Trust - Custom Liquid Version
  Optimized for direct copy-paste into the Theme Editor Custom Liquid block.
{% endcomment %}

<style>
  :root {
    --gs-navy: #0C3E61;
    --gs-gold: #BE982D;
    --gs-white: #FFFFFF;
  }

  .gs-trust-section {
    background-color: var(--gs-white);
    padding: 24px 0;
    width: 100%;
    font-family: inherit;
  }

  .gs-trust-container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 20px;
  }

  .gs-trust-header {
    text-align: center;
    margin-bottom: 35px;
  }

  .gs-trust-title {
    font-size: 32px;
    font-weight: 700;
    margin: 0;
    letter-spacing: -0.5px;
  }

  .gs-trust-navy { color: var(--gs-navy); }
  .gs-trust-gold { color: var(--gs-gold); margin-left: 2px; }

  .gs-trust-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 25px 40px;
  }

  .gs-trust-item {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .gs-trust-icon {
    flex-shrink: 0;
    width: 22px;
    height: 22px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .gs-trust-icon svg {
    width: 100%;
    height: 100%;
    stroke: var(--gs-gold);
    fill: none;
    stroke-width: 1.8px;
  }

  .gs-trust-label {
    color: var(--gs-navy);
    font-size: 14px;
    font-weight: 600;
    line-height: 1.2;
  }

  @media screen and (max-width: 768px) {
    .gs-trust-title { font-size: 24px; }

    .gs-trust-grid {
      grid-template-columns: repeat(2, 1fr);
      gap: 30px 15px;
    }

    .gs-trust-icon {
      width: 24px;
      height: 24px;
    }

    .gs-trust-label {
      font-size: 13px;
    }
  }
</style>

<div class="gs-trust-section">
  <div class="gs-trust-container">

    <div class="gs-trust-header">
      <h2 class="gs-trust-title">
        <span class="gs-trust-navy">GulfSouq</span><span class="gs-trust-gold">Trust</span>
      </h2>
    </div>

    <div class="gs-trust-grid">
      <div class="gs-trust-item">
        <div class="gs-trust-icon">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>
        </div>
        <div class="gs-trust-label">Secure Payment</div>
      </div>

      <div class="gs-trust-item">
        <div class="gs-trust-icon">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path><circle cx="12" cy="10" r="3"></circle></svg>
        </div>
        <div class="gs-trust-label">Delivery Tracking</div>
      </div>

      <div class="gs-trust-item">
        <div class="gs-trust-icon">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><polyline points="9 11 12 14 22 4"></polyline><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"></path></svg>
        </div>
        <div class="gs-trust-label">Easy Returns</div>
      </div>

      <div class="gs-trust-item">
        <div class="gs-trust-icon">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path><path d="M9 12l2 2 4-4"></path></svg>
        </div>
        <div class="gs-trust-label">Quality Assurance</div>
      </div>

      <div class="gs-trust-item">
        <div class="gs-trust-icon">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg>
        </div>
        <div class="gs-trust-label">Customer Support</div>
      </div>

      <div class="gs-trust-item">
        <div class="gs-trust-icon">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg>
        </div>
        <div class="gs-trust-label">Genuine Products</div>
      </div>

      <div class="gs-trust-item">
        <div class="gs-trust-icon">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg>
        </div>
        <div class="gs-trust-label">All India Delivery</div>
      </div>

      <div class="gs-trust-item">
        <div class="gs-trust-icon">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><rect x="1" y="4" width="22" height="16" rx="2" ry="2"></rect><line x1="1" y1="10" x2="23" y2="10"></line></svg>
        </div>
        <div class="gs-trust-label">Offline Payments</div>
      </div>

    </div>
  </div>
</div>
